const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const somalia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Somalia'))
    .geometry();

  // 2. Data Acquisition
  const soilMoistureCollection = 'NASA/SMAP/SPL4SMGP/007';
  const band = 'sm_surface';

  // April 2019
  const april2019 = ee.ImageCollection(soilMoistureCollection)
    .filterDate('2019-04-01', '2019-05-01')
    .filterBounds(somalia)
    .select(band);

  const size2019 = april2019.size().getInfo();
  console.log(`April 2019 Images: ${size2019}`);

  if (size2019 === 0) {
    console.log("No data for April 2019.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Historical April average (2015-2024, excluding 2019)
  const years = [2015, 2016, 2017, 2018, 2020, 2021, 2022, 2023, 2024];
  let aprilImages = ee.ImageCollection([]);

  for (let year of years) {
    const yearCol = ee.ImageCollection(soilMoistureCollection)
      .filterDate(`${year}-04-01`, `${year}-05-01`)
      .filterBounds(somalia)
      .select(band);
    aprilImages = aprilImages.merge(yearCol);
  }

  const sizeHistorical = aprilImages.size().getInfo();
  console.log(`Historical April Images: ${sizeHistorical}`);

  if (sizeHistorical === 0) {
    console.log("No historical data for April.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate means
  const mean2019Image = april2019.mean();
  const meanHistoricalImage = aprilImages.mean();

  // 4. Reduce region with pixel count validation
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats2019 = mean2019Image.reduceRegion({
    reducer: reducer,
    geometry: somalia,
    scale: 10000,
    maxPixels: 1e9
  });

  const statsHistorical = meanHistoricalImage.reduceRegion({
    reducer: reducer,
    geometry: somalia,
    scale: 10000,
    maxPixels: 1e9
  });

  const mean2019 = stats2019.get(`${band}_mean`).getInfo();
  const count2019 = stats2019.get(`${band}_count`).getInfo();
  const meanHistorical = statsHistorical.get(`${band}_mean`).getInfo();
  const countHistorical = statsHistorical.get(`${band}_count`).getInfo();

  console.log(`April 2019: Mean=${mean2019}, Pixels=${count2019}`);
  console.log(`Historical April: Mean=${meanHistorical}, Pixels=${countHistorical}`);

  // 5. Validation & Final Answer
  if (count2019 === 0 || countHistorical === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean2019 === null || meanHistorical === null || 
      isNaN(mean2019) || isNaN(meanHistorical)) {
    console.log("Calculation failed - invalid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare soil moisture
  if (mean2019 < meanHistorical) {
    console.log("April 2019 shows LOWER soil moisture than average.");
    console.log("<answer>A</answer>");
  } else {
    console.log("April 2019 does NOT show lower soil moisture than average.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
